// per PV-Überschuss die Pumpe und Heizung de/aktivieren
setState('javascript.0.Pool.TimerPumpe' /* VerzögerungPumpe */, false);
setState('javascript.0.Pool.TimerWB' /* VerzögerungWP */, false);
on({ id: [].concat(['0_userdata.0.ALIAS.EM24_HallGrid_PV_Ueberschuss']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  // Überwachung
  if (getState('javascript.0.Pool.STOP_Alive_Toggle_Fail').val == true) {
    setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, false);
    setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, false);
    setState('s7.0.DBs.DB1.V0_6' /* V0.6 PV Pumpe */, false);
    setState('s7.0.DBs.DB1.V0_7' /* V0.7 PV Heizung */, false);
    setState('javascript.0.Pool.TimerPumpe' /* VerzögerungPumpe */, false);
    setState('javascript.0.Pool.TimerWB' /* VerzögerungWP */, false);
    console.debug('Pool - EMERGENCY STOP - Alive Toggle !');
  } else if (getState('0_userdata.0.Victron.Grid_Halle_Überwachung').val == true) {
    if (getState('s7.0.DBs.DB1.V0_6').val == true || getState('s7.0.DBs.DB1.V0_7').val == true) {
      setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, false);
      setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, false);
      setState('s7.0.DBs.DB1.V0_6' /* V0.6 PV Pumpe */, false);
      setState('s7.0.DBs.DB1.V0_7' /* V0.7 PV Heizung */, false);
      setState('javascript.0.Pool.TimerPumpe' /* VerzögerungPumpe */, false);
      setState('javascript.0.Pool.TimerWB' /* VerzögerungWP */, false);
      console.debug('Pool - EMERGENCY STOP - keine PV Daten!');
    }
  } else {
    // PV Überschuss vorhanden ?
    if (getState('javascript.0.Pool.ÜberschussPumpeVorhanden').val == true) {
      // aktiv
      if (getState('s7.0.DBs.DB1.V0_0').val == true) {
        // WINTER
        setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, (getState('javascript.0.Pool.TimerPumpe').val == false && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > 200));
      } else {
        // SOMMER
        setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, (getState('javascript.0.Pool.TimerPumpe').val == false && getState('alias.0.EM24 New Grid.Power_Plus').val < 300 && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 200));
      }
    } else {
      // aktivieren
      // WINTER
      if (getState('s7.0.DBs.DB1.V0_0').val == true) {
        setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, (compareTime('07:00', null, '>') && getState('javascript.0.Pool.TimerPumpe').val == false && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 1000));
      } else {
        // SOMMER
        setState('javascript.0.Pool.ÜberschussPumpeVorhanden' /* ÜberschussPumpeVorhanden */, (compareTime('07:00', null, '>') && getState('javascript.0.Pool.TimerPumpe').val == false && getState('alias.0.EM24 New Grid.Power_Plus').val == 0 && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 1500));
      }
    }
    // Green Heat MS130 - nur wenn die Pumpe läuft
    if (getState('javascript.0.Pool.ÜberschussWPVorhanden').val == true) {
      // aktiv
      if (getState('s7.0.DBs.DB1.V0_0').val == true) {
        // WINTER
        setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, ((getState('s7.0.DBs.DB1.V0_6').val == true) && (getState('javascript.0.Pool.TimerWB').val == false) && (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val > 200) && ((!getState('go-e.0.allow_charging').val) || (getState('go-e.0.energy.power').val == 0)) && (!getState('go-e.1.allow_charging').val) && (!getState('go-e.2.allow_charging').val)));
      } else {
        // SOMMER
        setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, ((getState('s7.0.DBs.DB1.V0_6').val == true) && (getState('javascript.0.Pool.TimerWB').val == false) && (getState('alias.0.EM24 Hall Grid.Power').val < 0)));
      }
    } else {
      // aktivieren
      if (getState('s7.0.DBs.DB1.V0_0').val == true) {
        // WINTER
        setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, (getState('s7.0.DBs.DB1.V0_6').val == true && getState('javascript.0.Pool.TimerWB').val == false && getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 2000));
      } else {
        // SOMMER
        setState('javascript.0.Pool.ÜberschussWPVorhanden' /* ÜberschussWPVorhanden */, ((getState('s7.0.DBs.DB1.V0_6').val == true) && (getState('javascript.0.Pool.TimerWB').val == false) && (getState('alias.0.EM24 Hall Grid.Power').val < -4000) && (!getState('go-e.1.allow_charging').val)));
      }
    }
    // Debug
    if (getState('javascript.0.Pool.ÜberschussPumpeVorhanden').val != old_C3_9CberschussPumpe || getState('javascript.0.Pool.ÜberschussWPVorhanden').val != old_C3_9CberschussWP) {
      console.debug((String(', P-Fronius: ' + String(String(getState('alias.0.Fronius.AC-Power').val) + String(', Überschuss: ' + String(getState('alias.0.EM24 Hall Grid.PV_Überschuss').val)))) + ''));
      old_C3_9CberschussPumpe = getState('javascript.0.Pool.ÜberschussPumpeVorhanden').val;
      old_C3_9CberschussWP = getState('javascript.0.Pool.ÜberschussWPVorhanden').val;
    }
    // Pumpe 750W de/aktivieren
    if (getState('javascript.0.Pool.ÜberschussPumpeVorhanden').val == true && getState('s7.0.DBs.DB1.V0_6').val == false && getState('javascript.0.Pool.TimerPumpe').val == false) {
      setState('s7.0.DBs.DB1.V0_6' /* V0.6 PV Pumpe */, true);
      console.debug('Pool - PV hat genug Überschuss für die Pumpe');
    } else if (getState('javascript.0.Pool.ÜberschussPumpeVorhanden').val == false && getState('s7.0.DBs.DB1.V0_6').val == true) {
      setState('s7.0.DBs.DB1.V0_6' /* V0.6 PV Pumpe */, false);
      setState('javascript.0.Pool.TimerPumpe' /* VerzögerungPumpe */, true);
      setStateDelayed('javascript.0.Pool.TimerPumpe' /* VerzögerungPumpe */, false, 300000, false);
      console.debug((['Pool - PV hat NICHT genug Überschuss für die Pumpe, PVFroniusÜ: ',getState('alias.0.EM24 Hall Grid.PV_Überschuss').val,', PVFronius: ',getState('alias.0.Fronius.AC-Power').val,'','','',''].join('')));
    }
    // Green Heat MS130 2kW 12A de/aktivieren
    if (getState('javascript.0.Pool.ÜberschussWPVorhanden').val == true && getState('s7.0.DBs.DB1.V0_7').val == false && getState('javascript.0.Pool.TimerWB').val == false) {
      setState('s7.0.DBs.DB1.V0_7' /* V0.7 PV Heizung */, true);
      console.debug('Pool - PV hat genug Überschuss für die Heizung');
    } else if (getState('javascript.0.Pool.ÜberschussWPVorhanden').val == false && getState('s7.0.DBs.DB1.V0_7').val == true) {
      setState('s7.0.DBs.DB1.V0_7' /* V0.7 PV Heizung */, false);
      setState('javascript.0.Pool.TimerWB' /* VerzögerungWP */, true);
      if (getState('s7.0.DBs.DB1.V0_0').val == true) {
        setStateDelayed('javascript.0.Pool.TimerWB' /* VerzögerungWP */, false, 300000, false);
      } else {
        setStateDelayed('javascript.0.Pool.TimerWB' /* VerzögerungWP */, false, 300000, false);
      }
      console.debug((['Pool - PV hat NICHT genug Überschuss für die Heizung, PVFroniusÜ: ',getState('alias.0.EM24 Hall Grid.PV_Überschuss').val,', PVFronius: ',getState('alias.0.Fronius.AC-Power').val,'','','',''].join('')));
    }
  }
});

// Winterbetrieb - Nachtabschaltung der Umwälzpume
schedule({ astro: 'sunset', shift: -30 }, async () => {
  if (getState('s7.0.DBs.DB1.V0_0').val && getState('s7.0.DBs.DB1.VW2').val >= 60) {
    if (!getState('s7.0.DBs.DB1.V0_1').val) {
      setState('s7.0.DBs.DB1.V0_1' /* V0.1 Pumpe deaktivieren */, true);
      sendTo('telegram.0', 'send', {
        text: 'Pool - Temp >6°C, Nachtabschaltung der Umwälzpumpe aktiviert',
      });
      console.log('telegram: ' + 'Pool - Temp >6°C, Nachtabschaltung der Umwälzpumpe aktiviert');
    }
  }
});
schedule({ astro: 'sunrise', shift: 60 }, async () => {
  if (getState('s7.0.DBs.DB1.V0_0').val && getState('s7.0.DBs.DB1.V0_1').val) {
    setState('s7.0.DBs.DB1.V0_1' /* V0.1 Pumpe deaktivieren */, false);
    sendTo('telegram.0', 'send', {
      text: 'Pool - Nachtabschaltung der Umwälzpumpe deaktiviert',
    });
    console.log('telegram: ' + 'Pool - Nachtabschaltung der Umwälzpumpe deaktiviert');
  }
});


